<template><VContainer class="setup"><VCard class="pa-6 pa-md-10" max-width="720"><img src="@/assets/logo.svg" alt="Xeler" class="logo"><template v-if="completed"><h1>Configuración completada correctamente</h1><p>Cuenta creada correctamente. Inicia sesión para continuar.</p><VBtn color="primary" to="/login">Ir a iniciar sesión</VBtn></template><template v-else-if="unavailable"><h1>La configuración inicial ya fue completada.</h1><VBtn to="/login">Ir a iniciar sesión</VBtn></template><template v-else><h1>Bienvenido a Xeler</h1><p>Vamos a configurar la cuenta principal de administración.</p><VAlert v-if="error" type="error" class="mb-4">{{error}}</VAlert><VForm @submit.prevent="submit"><h2>Datos principales</h2><VRow><VCol cols="12" md="6"><VTextField v-model="form.first_name" label="Nombre" :error-messages="errors.first_name"/></VCol><VCol cols="12" md="6"><VTextField v-model="form.last_name" label="Apellido" :error-messages="errors.last_name"/></VCol></VRow><VTextField v-model="form.email" label="Correo electrónico" type="email" autocomplete="email" :error-messages="errors.email"/><VTextField v-model="form.username" label="Nombre de usuario" autocomplete="username" :error-messages="errors.username"/><VRow><VCol cols="12" md="5"><VSelect v-model="form.code_phone" label="País / Indicativo" :items="countries"/></VCol><VCol><VTextField v-model="form.phone" label="Teléfono" inputmode="numeric" :error-messages="errors.phone"/></VCol></VRow><h2>Seguridad</h2><VTextField v-model="form.password" label="Contraseña" :type="show?'text':'password'" autocomplete="new-password" :append-inner-icon="show?'mdi-eye-off':'mdi-eye'" @click:append-inner="show=!show" :error-messages="errors.password"/><PasswordRequirements :password="form.password"/><VTextField v-model="form.password_confirmation" label="Confirmar contraseña" :type="showConfirm?'text':'password'" autocomplete="new-password" :append-inner-icon="showConfirm?'mdi-eye-off':'mdi-eye'" @click:append-inner="showConfirm=!showConfirm" :error-messages="errors.password_confirmation"/><VBtn type="submit" color="primary" size="large" block :loading="loading">Crear cuenta principal</VBtn></VForm></template></VCard></VContainer></template>
<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue'; import {useRouter,useRoute} from 'vue-router'; import PasswordRequirements from '@/components/PasswordRequirements.vue'; import {setupApi} from '@/services/adminSetupApi';
const router=useRouter(),route=useRoute(),loading=ref(false),completed=ref(false),unavailable=ref(false),error=ref(''),errors=ref<Record<string,string[]>>({}),show=ref(false),showConfirm=ref(false);
const form=reactive({first_name:'',last_name:'',email:'',username:'',code_phone:'57',phone:'',password:'',password_confirmation:''}); const countries=[{title:'Colombia (+57)',value:'57'},{title:'México (+52)',value:'52'},{title:'Estados Unidos (+1)',value:'1'},{title:'España (+34)',value:'34'}];
onMounted(async()=>{try{const s=await setupApi.status();if(!s.data.setup_required){unavailable.value=true;return}const token=String(route.query.token||'');if(!token){error.value='Necesitas abrir el enlace de configuración autorizado.';return}await setupApi.exchange(token);await router.replace('/configuracion-inicial')}catch(e:any){error.value=e.response?.data?.message||'No fue posible validar el enlace de configuración.'}});
async function submit(){loading.value=true;error.value='';errors.value={};try{await setupApi.create(form);completed.value=true}catch(e:any){errors.value=e.response?.data?.errors||{};error.value=e.response?.data?.message||'No fue posible crear la cuenta.'}finally{loading.value=false}}
</script><style scoped>.setup{min-height:100vh;display:grid;place-items:center;background:#f3f6fb}.logo{width:150px;margin-bottom:1.5rem}h1{color:#16345f;margin-bottom:.5rem}h2{font-size:1.15rem;margin:1.25rem 0 .75rem}</style>
